def transform(grid):
    n = len(grid[0])
    apex = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0] * n for _ in range(n)]

    for r in range(n):
        left, right = apex - r, apex + r
        for c in range(max(0, left), min(n - 1, right) + 1):
            if c == left or c == right:
                out[r][c] = 2
            elif (c - apex - r) % 4 == 0:
                out[r][c] = 1

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    border_cells = set()

    # Find monochromatic rectangular outlines as connected components.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = set()
            while stack:
                y, x = stack.pop()
                comp.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                        grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in comp)
            r1 = max(y for y, x in comp)
            c0 = min(x for y, x in comp)
            c1 = max(x for y, x in comp)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue

            perimeter = set()
            for x in range(c0, c1 + 1):
                perimeter.add((r0, x))
                perimeter.add((r1, x))
            for y in range(r0, r1 + 1):
                perimeter.add((y, c0))
                perimeter.add((y, c1))

            if comp == perimeter:
                frames.append((r0, r1, c0, c1, color))
                border_cells.update(perimeter)

    # Count the scattered pixels by color.
    counts = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r, c) not in border_cells:
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1

    out = [[0] * w for _ in range(h)]
    for r, c in border_cells:
        out[r][c] = grid[r][c]

    used = set()
    for r0, r1, c0, c1, border_color in frames:
        cells = [(r, c) for r in range(r0 + 1, r1)
                 for c in range(c0 + 1, c1) if (r + c) % 2 == 0]
        needed = len(cells)
        candidates = [color for color, count in counts.items()
                      if color not in used and count == needed]
        if not candidates:
            candidates = [color for color in counts if color not in used]
            if candidates:
                candidates.sort(key=lambda color: abs(counts[color] - needed))
        if candidates:
            fill_color = candidates[0]
            used.add(fill_color)
            for r, c in cells:
                out[r][c] = fill_color

    return out

