def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] != bg]
    out = [row[:] for row in grid]

    if not points:
        return out

    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)

    # Complete the rectangular outline.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if (r == r0 or r == r1 or c == c0 or c == c1) and grid[r][c] == bg:
                out[r][c] = 2

    # Bridge short interruptions in aligned marks.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] != bg]
        for a, b in zip(cols, cols[1:]):
            if 2 <= b - a <= 3 and all(grid[r][c] == bg for c in range(a + 1, b)):
                for c in range(a + 1, b):
                    out[r][c] = 2

    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != bg]
        for a, b in zip(rows, rows[1:]):
            if 2 <= b - a <= 3 and all(grid[r][c] == bg for r in range(a + 1, b)):
                for r in range(a + 1, b):
                    out[r][c] = 2

    return out

