def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid[6:]]

    # Locate the 1-shape below the divider.
    ones = [(r - 6, c) for r in range(6, h) for c in range(w) if grid[r][c] == 1]
    if not ones:
        return out
    target_top = min(r for r, c in ones)
    target_left = min(c for r, c in ones)

    # Find the colored shape above the divider, excluding the two reference shapes.
    color = next(
        grid[r][c]
        for r in range(5)
        for c in range(w)
        if grid[r][c] not in (0, 1, 2, 5)
    )
    cells = [(r, c) for r in range(5) for c in range(w) if grid[r][c] == color]
    top = min(r for r, c in cells)
    left = min(c for r, c in cells)

    # Stack it immediately above the lower 1-shape, aligned to its bounding box.
    for r, c in cells:
        rr = target_top - (top and (max(x for x, y in cells) - r + 1))
        cc = target_left + (c - left)
        if 0 <= rr < len(out) and 0 <= cc < w:
            out[rr][cc] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])

    # A separator divides the grid into two equal-sized panels.
    candidates = []
    if h % 2 == 1:
        r = h // 2
        if len(set(grid[r])) == 1:
            candidates.append(("row", r, grid[r][0]))
    if w % 2 == 1:
        c = w // 2
        if len({grid[r][c] for r in range(h)}) == 1:
            candidates.append(("col", c, grid[0][c]))

    for axis, sep, sep_color in candidates:
        if axis == "row":
            a, b = grid[:sep], grid[sep + 1:]
        else:
            a = [row[:sep] for row in grid]
            b = [row[sep + 1:] for row in grid]

        shared = ({v for row in a for v in row} &
                  {v for row in b for v in row})
        shared.discard(sep_color)
        if not shared:
            continue

        color = next(iter(shared))
        return [
            [3 if a[r][c] == color and b[r][c] == color else color
             for c in range(len(a[0]))]
            for r in range(len(a))
        ]

    return grid

def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []

    # Each framed tile is a 4-connected nonzero component.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                            grid[nx][ny] != 0 and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            r0 = min(x for x, _ in cells)
            r1 = max(x for x, _ in cells)
            c0 = min(y for _, y in cells)
            c1 = max(y for _, y in cells)
            boxes.append((r0, r1, c0, c1))

    if not boxes:
        return [row[:] for row in grid]

    # Keep full-sized repeated tiles; edge-cropped tiles are ignored.
    dims = Counter((r1 - r0 + 1, c1 - c0 + 1)
                  for r0, r1, c0, c1 in boxes)
    tile_h, tile_w = dims.most_common(1)[0][0]
    tiles = []
    for r0, r1, c0, c1 in boxes:
        if (r1 - r0 + 1, c1 - c0 + 1) != (tile_h, tile_w):
            continue
        interior = [grid[r][c]
                    for r in range(r0 + 1, r1)
                    for c in range(c0 + 1, c1)]
        if not interior:
            continue
        color = Counter(interior).most_common(1)[0][0]
        tiles.append((r0, r1, c0, c1, color))

    if not tiles:
        return [row[:] for row in grid]

    common = Counter(t[4] for t in tiles).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Join repeated non-background interior colors, filling only blank gaps.
    for i, a in enumerate(tiles):
        ar0, ar1, ac0, ac1, color = a
        if color == common:
            continue
        for b in tiles[i + 1:]:
            br0, br1, bc0, bc1, bcolor = b
            if bcolor != color:
                continue

            if ar0 == br0:  # same tile row
                left, right = (a, b) if ac0 < bc0 else (b, a)
                for r in range(max(ar0, br0) + 1, min(ar1, br1)):
                    for c in range(left[3] + 1, right[2]):
                        if out[r][c] == 0:
                            out[r][c] = color

            if ac0 == bc0:  # same tile column
                top, bottom = (a, b) if ar0 < br0 else (b, a)
                for c in range(max(ac0, bc0) + 1, min(ac1, bc1)):
                    for r in range(top[1] + 1, bottom[0]):
                        if out[r][c] == 0:
                            out[r][c] = color

    return out

def transform(grid):
    out = [row[:] for row in grid]
    cols = list(range(1, len(grid[0]), 3))
    vectors = [([grid[r][c] for r in range(len(grid))], c) for c in cols]
    vectors.sort(key=lambda item: -sum(v == 0 for v in item[0]))
    for c, (vec, _) in zip(cols, vectors):
        for r, v in enumerate(vec):
            out[r][c] = v
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = [0, 0]  # stem above, stem below

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            component = set()
            while stack:
                cr, cc = stack.pop()
                component.add((cr, cc))
                for nr, nc in ((cr - 1, cc), (cr + 1, cc),
                               (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w
                            and grid[nr][nc] == 2
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            stem_above = False
            stem_below = False
            for cr, cc in component:
                if all((cr, cc + offset) in component for offset in (-1, 0, 1)):
                    if (cr - 1, cc) in component:
                        stem_above = True
                    if (cr + 1, cc) in component:
                        stem_below = True

            if stem_above:
                counts[0] += 1
            elif stem_below:
                counts[1] += 1

    out = [[0] * 6 for _ in range(3)]
    slots = [(0, 0), (2, 0), (0, 2), (2, 2)]
    for color, count, start_col in ((3, counts[0], 0), (1, counts[1], 3)):
        for rr, cc in slots[:count]:
            out[rr][start_col + cc] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    mask = [[grid[r][c] != 0 for c in range(w)] for r in range(h)]
    out = [[0 for _ in range(w * 3)] for _ in range(h * 3)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color:
                for a in range(3):
                    for b in range(3):
                        if not mask[a][b]:
                            out[r * 3 + a][c * 3 + b] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                grid[ny][nx] != bg and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            comps.append(comp)

    seed = max(comps, key=len)
    r0 = min(r for r, c in seed)
    r1 = max(r for r, c in seed)
    c0 = min(c for r, c in seed)
    c1 = max(c for r, c in seed)
    pattern = [[grid[r][c] for c in range(c0, c1 + 1)]
               for r in range(r0, r1 + 1)]
    ar, ac = (r1 - r0) // 2, (c1 - c0) // 2

    out = [row[:] for row in grid]
    for comp in comps:
        if comp is seed:
            continue
        for mr, mc in comp:
            for pr in range(len(pattern)):
                for pc in range(len(pattern[0])):
                    y, x = mr + pr - ar, mc + pc - ac
                    if 0 <= y < h and 0 <= x < w:
                        out[y][x] = pattern[pr][pc]
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    segments = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if abs(r2 - r1) == abs(c2 - c1) and r2 != r1:
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                segments.append((r1, c1, r2, c2, dr, dc))
                r, c = r1, c1
                while True:
                    if out[r][c] == bg:
                        out[r][c] = 1
                    if (r, c) == (r2, c2):
                        break
                    r += dr
                    c += dc

    for r, c in sixes:
        for r1, c1, r2, c2, dr, dc in segments:
            if (r - r1) * dc == (c - c1) * dr and \
               min(r1, r2) <= r <= max(r1, r2) and \
               min(c1, c2) <= c <= max(c1, c2):
                # Extend perpendicular to the 1-line.
                step_c = -dr * dc
                for k in range(-max(h, w), max(h, w) + 1):
                    rr = r + k
                    cc = c + k * step_c
                    if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = 6
                break

    return out

def transform(grid):
    top = grid[:4]
    bottom = grid[5:9]
    return [
        [3 if top[r][c] != 0 or bottom[r][c] != 0 else 0 for c in range(5)]
        for r in range(4)
    ]

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Infer the repeating diagonal pattern from nonzero interior cells.
    best = None
    for period in range(2, 16):
        counts = [{} for _ in range(period)]
        for r in range(3, h):
            for c in range(3, w):
                value = grid[r][c]
                if value:
                    bucket = counts[(r + c) % period]
                    bucket[value] = bucket.get(value, 0) + 1

        mapping = {}
        matched = total = 0
        for residue, bucket in enumerate(counts):
            if bucket:
                value, number = max(bucket.items(), key=lambda item: item[1])
                mapping[residue] = value
                matched += number
                total += sum(bucket.values())

        score = matched / total if total else 0
        if best is None or score > best[0]:
            best = (score, mapping, period)
        if score >= 0.96:
            best = (score, mapping, period)
            break

    _, mapping, period = best
    result = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if result[r][c] != 0:
                continue
            if r < 2 or c < 2:
                result[r][c] = 1
            elif r == 2 or c == 2:
                result[r][c] = 4
            else:
                result[r][c] = mapping.get((r + c) % period, 1)

    return result

def transform(grid):
    divider = next(r for r, row in enumerate(grid) if all(v == 5 for v in row))
    colors = {v for row in grid for v in row if v not in (0, 5)}
    differences = {}
    for color in colors:
        above = sum(v == color for row in grid[:divider] for v in row)
        below = sum(v == color for row in grid[divider + 1:] for v in row)
        differences[color] = abs(below - above)
    chosen = max(colors, key=lambda color: differences[color])
    return [[chosen, chosen], [chosen, chosen]]

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    fill_color = {(3, 3): 8, (5, 5): 4, (7, 7): 3}

    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            for c1 in range(w):
                for c2 in range(c1 + 2, w):
                    if (r2 - r1 - 1, c2 - c1 - 1) not in fill_color:
                        continue
                    if not (all(grid[r1][c] == 2 and grid[r2][c] == 2
                                for c in range(c1, c2 + 1)) and
                            all(grid[r][c1] == 2 and grid[r][c2] == 2
                                for r in range(r1, r2 + 1))):
                        continue
                    interior = [grid[r][c]
                                for r in range(r1 + 1, r2)
                                for c in range(c1 + 1, c2)]
                    if interior.count(2) != 1 or any(x not in (0, 2) for x in interior):
                        continue
                    color = fill_color[(r2 - r1 - 1, c2 - c1 - 1)]
                    for r in range(r1 + 1, r2):
                        for c in range(c1 + 1, c2):
                            if grid[r][c] == 0:
                                out[r][c] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    d = None
    orient = None
    start = None

    # Locate a solid 3-colored horizontal or vertical separator.
    for r in range(h):
        if all(v == 3 for v in grid[r]):
            a = r
            while r < h and all(v == 3 for v in grid[r]):
                r += 1
            if r - a >= 2:
                d, orient, start = r - a, "h", a
                break
            r -= 1

    if d is None:
        for c in range(w):
            if all(grid[r][c] == 3 for r in range(h)):
                a = c
                while c < w and all(grid[r][c] == 3 for r in range(h)):
                    c += 1
                if c - a >= 2:
                    d, orient, start = c - a, "v", a
                    break
                c -= 1

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 3:
                out[r][c] = 0

    if d is None:
        return out

    pitch = d + 1
    nr, nc = (h + 1) // pitch, (w + 1) // pitch

    # Read the repeated d-by-d tile from a non-separator position.
    best = None
    best_count = -1
    for i in range(nr):
        for j in range(nc):
            r0, c0 = i * pitch, j * pitch
            if orient == "h" and start <= r0 < start + d:
                continue
            if orient == "v" and start <= c0 < start + d:
                continue
