from functools import lru_cache

def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not cells:
        return [row[:] for row in grid]

    index = {p: i for i, p in enumerate(cells)}
    tiles = []
    by_cell = [[] for _ in cells]

    for r in range(h - 1):
        for c in range(w - 1):
            corners = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            present = [p for p in corners if p in index]
            if len(present) == 4:
                color = 1
            elif len(present) == 3:
                missing = next(i for i, p in enumerate(corners) if p not in index)
                color = {0: 2, 1: 4, 2: 3, 3: 1}[missing]
            else:
                continue

            mask = 0
            for p in present:
                mask |= 1 << index[p]
            tid = len(tiles)
            tiles.append((mask, color, len(present) == 4))
            for p in present:
                by_cell[index[p]].append(tid)

    full = (1 << len(cells)) - 1

    @lru_cache(None)
    def solve(rem):
        if rem == 0:
            return ()

        best = None
        bits = rem
        while bits:
            bit = bits & -bits
            bits -= bit
            i = bit.bit_length() - 1
            options = [
                tid for tid in by_cell[i]
                if tiles[tid][0] & rem == tiles[tid][0]
            ]
            if not options:
                return None
            options.sort(key=lambda tid: (not tiles[tid][2], tiles[tid][1]))
            if best is None or len(options) < len(best):
                best = options
                if len(best) == 1:
                    break

        for tid in best:
            mask = tiles[tid][0]
            result = solve(rem ^ mask)
            if result is not None:
                return (tid,) + result
        return None

    solution = solve(full)
    out = [[0] * w for _ in range(h)]
    if solution is None:
        return [row[:] for row in grid]

    for tid in solution:
        mask, color, _ = tiles[tid]
        while mask:
            bit = mask & -mask
            mask -= bit
            r, c = cells[bit.bit_length() - 1]
            out[r][c] = color

    return out

