                        counts[v] = counts.get(v, 0) + 1
            if counts:
                value = max(counts, key=counts.get)
                updates.append((r, c, value))

        if not updates:
            break
        for r, c, value in updates:
            out[r][c] = value
            if 0 <= c < n and 0 <= r < m:
                out[c][r] = value
            pending.discard((r, c))
            pending.discard((c, r))

    return out

def transform(grid):
