    for kind in range(4):  # row, column, r-c, r+c
        groups = {}
        for r, c, v in cells:
            idx = (r, c, r - c, r + c)[kind]
            if idx in groups and groups[idx] != v:
                break
            groups[idx] = v
        else:
            residues = {}
            for idx, v in groups.items():
                residue = idx % k
                if residue in residues and residues[residue] != v:
                    break
                residues[residue] = v
            else:
                candidates.append((len(groups), len(residues), kind, residues))

    if not candidates:
        return [row[:] for row in grid]

    _, _, kind, residues = max(candidates)
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            idx = (r, c, r - c, r + c)[kind]
            row.append(residues[idx % k])
        out.append(row)
    return out

