def transform(grid):
    h, w = len(grid), len(grid[0])
    anchors = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    if len(anchors) < 2:
        return [row[:] for row in grid]

    def component(start):
        seen = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < h and 0 <= nc < w and
                        (nr, nc) not in seen and grid[nr][nc] != 0):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
        return seen

    comps = [component(a) for a in anchors]
    donor_i = max(range(len(anchors)), key=lambda i: len(comps[i]))
    donor, target = anchors[donor_i], anchors[1 - donor_i]
    out = [row[:] for row in grid]
    out[target[0]][target[1]] = 0
    dr, dc = target[0] - donor[0], target[1] - donor[1]

    for r, c in comps[donor_i]:
        if (r, c) == donor:
            continue
        nr, nc = r + dr, c + dc
        if 0 <= nr < h and 0 <= nc < w:
            out[nr][nc] = grid[r][c]
    return out

def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    outside = [[False] * w for _ in range(h)]
    q = deque()

    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (0 <= nr < h and 0 <= nc < w and
                    grid[nr][nc] == background and not outside[nr][nc]):
                outside[nr][nc] = True
                q.append((nr, nc))

    result = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background and not outside[r][c]:
                result[r][c] = 4
    return result

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find 4-connected components of 1s.
    comp_id = [[-1] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or comp_id[r][c] != -1:
                continue
            k = len(comps)
            stack = [(r, c)]
            comp_id[r][c] = k
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1
                            and comp_id[ny][nx] == -1):
                        comp_id[ny][nx] = k
                        stack.append((ny, nx))
            comps.append(cells)

    # Flood-fill exterior zero cells using 4-connectivity.
    exterior = [[False] * w for _ in range(h)]
    stack = []
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not exterior[r][c]:
                exterior[r][c] = True
                stack.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not exterior[r][c]:
                exterior[r][c] = True
                stack.append((r, c))
    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and not exterior[nr][nc]):
                exterior[nr][nc] = True
                stack.append((nr, nc))

    # Components bordering an enclosed zero region get an inner and outer halo.
    qualifying = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and not exterior[r][c]:
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                        qualifying.add(comp_id[nr][nc])

    # Inner halo (3) and outer halo (2), using 8-neighbor adjacency.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            near_qualifying = False
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1
                            and comp_id[nr][nc] in qualifying):
                        near_qualifying = True
            if near_qualifying:
                out[r][c] = 3 if not exterior[r][c] else 2

    return out

