def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not fours or not sixes:
        return out

    rmin = min(r for r, c in fours)
    rmax = max(r for r, c in fours)
    cmin = min(c for r, c in fours)
    cmax = max(c for r, c in fours)
    srmin = min(r for r, c in sixes)
    srmax = max(r for r, c in sixes)
    scmin = min(c for r, c in sixes)
    scmax = max(c for r, c in sixes)

    sixset = set(sixes)
    vertical_sym = all((r, scmin + scmax - c) in sixset for r, c in sixes)
    horizontal_sym = all((srmin + srmax - r, c) in sixset for r, c in sixes)

    if vertical_sym and not horizontal_sym:
        axis = "vertical"
    elif horizontal_sym and not vertical_sym:
        axis = "horizontal"
    elif scmax - scmin > srmax - srmin:
        axis = "horizontal"
    else:
        axis = "vertical"

    for r, c in sixes:
        out[r][c] = 0

    if axis == "vertical":
        six_c = sum(c for r, c in sixes) / len(sixes)
        four_c = sum(c for r, c in fours) / len(fours)
        if six_c >= four_c:
            for r, c in fours:
                nc = 2 * cmax + 1 - c
                if 0 <= nc < w:
                    out[r][nc] = 4
        else:
            for r, c in fours:
                nc = 2 * cmin - 1 - c
                if 0 <= nc < w:
                    out[r][nc] = 4
    else:
        six_r = sum(r for r, c in sixes) / len(sixes)
        four_r = sum(r for r, c in fours) / len(fours)
        if six_r >= four_r:
            for r, c in fours:
                nr = 2 * rmax + 1 - r
                if 0 <= nr < h:
                    out[nr][c] = 4
        else:
            for r, c in fours:
                nr = 2 * rmin - 1 - r
                if 0 <= nr < h:
                    out[nr][c] = 4

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            if v:
                counts[v] = counts.get(v, 0) + 1

    inner = min(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)

    inner_points = [(r, c) for r in range(h) for c in range(w)
                    if grid[r][c] == inner]
    ir0 = min(r for r, c in inner_points)
    ir1 = max(r for r, c in inner_points)
    ic0 = min(c for r, c in inner_points)
    ic1 = max(c for r, c in inner_points)

    ih, iw = ir1 - ir0 + 1, ic1 - ic0 + 1
    if ih == iw:
        expand = ih
    else:
        expand = min(ir0 - r0, r1 - ir1, ic0 - c0, c1 - ic1)

    out = [row[:] for row in grid]
    for r in range(max(0, r0 - expand), min(h, r1 + expand + 1)):
        for c in range(max(0, c0 - expand), min(w, c1 + expand + 1)):
            if out[r][c] == 0:
                out[r][c] = inner
    return out

