def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the centers of the 3x3 motifs.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    if not centers:
        return out

    row_max = max(sum(v == 2 for v in row) for row in grid)
    col_max = max(sum(grid[r][c] == 2 for r in range(h)) for c in range(w))
    vertical_scaffold = col_max / h >= row_max / w

    def paint_one(r, c):
        if 0 <= r < h and 0 <= c < w and out[r][c] == 0:
            out[r][c] = 1

    if vertical_scaffold:
        scaffold = [
            c for c in range(w)
            if sum(grid[r][c] == 2 for r in range(h)) >= h / 2
        ]
        for r, c in centers:
            # Extend the motif's center line horizontally.
            for cc in range(w):
                paint_one(r, cc)
            # Mark a 1-colored motif at every scaffold crossing.
            for x in scaffold:
                for rr in range(r - 1, r + 2):
                    for cc in range(x - 1, x + 2):
                        paint_one(rr, cc)
    else:
        scaffold = [
            r for r in range(h)
            if sum(v == 2 for v in grid[r]) >= w / 2
        ]
        for r, c in centers:
            # Extend the motif's center line vertically.
            for rr in range(h):
                paint_one(rr, c)
            # Mark a 1-colored motif at every scaffold crossing.
            for y in scaffold:
                for rr in range(y - 1, y + 2):
                    for cc in range(c - 1, c + 2):
                        paint_one(rr, cc)

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                points.setdefault(grid[r][c], []).append((r, c))

    def put(r, c, value):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = value

    # Color 1: a short eastward trail with a raised endpoint.
    for r, c in points.get(1, []):
        put(r, c + 1, 5)
        put(r, c + 2, 5)
        put(r - 1, c + 2, 1)

    # Color 2: extend four cells west.
    for r, c in points.get(2, []):
        for d in range(1, 5):
            put(r, c - d, 2 if d == 4 else 5)

    # Color 3: extend three cells south.
    for r, c in points.get(3, []):
        for d in range(1, 4):
            put(r + d, c, 3 if d == 3 else 5)

    # Color 6: extend six cells north.
    for r, c in points.get(6, []):
        for d in range(1, 7):
            put(r - d, c, 6 if d == 6 else 5)

    # Where the 2 and 3 trails cross, mark the crossing and draw the
    # diagonal 4 trail southwest.
    for r2, c2 in points.get(2, []):
        for r3, c3 in points.get(3, []):
            if c2 - 4 <= c3 <= c2 and r3 <= r2 <= r3 + 3:
                put(r2, c3, 4)
                d = 1
                while r2 + d < h and c3 - d >= 0:
                    put(r2 + d, c3 - d, 4)
                    d += 1

    # Preserve all input markers.
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                out[r][c] = grid[r][c]
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid line that acts as the barrier.
    barrier = None
    for r in range(h):
        if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r]):
            barrier = ("row", r)
            break
    if barrier is None:
        for c in range(w):
            if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
                barrier = ("col", c)
                break
    if barrier is None:
        return [row[:] for row in grid]

    out = [[0] * w for _ in range(h)]
    fixed = set()
    if barrier[0] == "row":
        _, br = barrier
        for c in range(w):
            out[br][c] = grid[br][c]
            fixed.add((br, c))
        dr, dc = (-1, 0) if br < h // 2 else (1, 0)
    else:
        _, bc = barrier
        for r in range(h):
            out[r][bc] = grid[r][bc]
            fixed.add((r, bc))
        dr, dc = (0, -1) if bc < w // 2 else (0, 1)

    # Extract connected, same-color objects, excluding the barrier.
    seen = set(fixed)
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w
                            and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            objects.append(cells)

    # Move objects nearest the barrier first.
    if dr < 0:
        objects.sort(key=lambda cells: min(r for r, _ in cells))
    elif dr > 0:
        objects.sort(key=lambda cells: -max(r for r, _ in cells))
    elif dc < 0:
        objects.sort(key=lambda cells: min(c for _, c in cells))
    else:
        objects.sort(key=lambda cells: -max(c for _, c in cells))

    for cells in objects:
        color = grid[cells[0][0]][cells[0][1]]
        shift = 0
        while True:
            next_cells = [(r + dr * (shift + 1), c + dc * (shift + 1))
                          for r, c in cells]
            if any(not (0 <= nr < h and 0 <= nc < w) or out[nr][nc] != 0
                   for nr, nc in next_cells):
                break
            shift += 1
        for r, c in cells:
            out[r + dr * shift][c + dc * shift] = color

    return out

